import numpy as np
from scipy.optimize import minimize
from functools import partial

def generate_initial_guess(num_circles=26):
    rows = 6
    cols = 5
    d = 1.0 / (cols - 1)  # Horizontal spacing
    vertical_spacing = (np.sqrt(3)/2) * d  # Vertical spacing for hexagonal pattern
    positions = []

    # Generate main grid
    for i in range(rows):
        for j in range(cols):
            x = j * d
            y = i * vertical_spacing
            if i % 2 == 1:
                x += d / 2
            # Ensure positions stay within square
            x = np.clip(x, 0.0 + 1e-12, 1.0 - 1e-12)
            y = np.clip(y, 0.0 + 1e-12, 1.0 - 1e-12)
            positions.append((x, y))

    # Remove 4 circles to reach num_circles
    positions = positions[:num_circles]

    # Calculate minimal distance between adjacent centers
    min_distance = vertical_spacing
    r_initial = min_distance * 0.4  # Safe initial radius

    # Ensure positions are within [0,1]^2 with some buffer
    positions = np.array(positions)
    positions = np.clip(positions, 0.0 + 1e-12, 1.0 - 1e-12)
    return positions, np.full(num_circles, r_initial)

def constraint_x_min(vars, i):
    centers = vars[:26*2].reshape(26, 2)
    radii = vars[26*2:]
    return centers[i][0] - radii[i]

def constraint_x_max(vars, i):
    centers = vars[:26*2].reshape(26, 2)
    radii = vars[26*2:]
    return 1.0 - (centers[i][0] + radii[i])

def constraint_y_min(vars, i):
    centers = vars[:26*2].reshape(26, 2)
    radii = vars[26*2:]
    return centers[i][1] - radii[i]

def constraint_y_max(vars, i):
    centers = vars[:26*2].reshape(26, 2)
    radii = vars[26*2:]
    return 1.0 - (centers[i][1] + radii[i])

def constraint_pairwise(vars, i, j):
    centers = vars[:26*2].reshape(26, 2)
    radii = vars[26*2:]
    x1, y1 = centers[i]
    x2, y2 = centers[j]
    r1 = radii[i]
    r2 = radii[j]
    dist = np.sqrt((x1 - x2)**2 + (y1 - y2)**2)
    return dist - (r1 + r2)

def validate_packing(centers, radii):
    n = centers.shape[0]
    if np.isnan(centers).any() or np.isnan(radii).any():
        return False
    for i in range(n):
        if radii[i] < 0:
            return False
    for i in range(n):
        x, y = centers[i]
        r = radii[i]
        if x - r < -1e-12 or x + r > 1 + 1e-12 or y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            if dist < radii[i] + radii[j] - 1e-12:
                return False
    return True

def run_packing():
