    variables_initial = np.concatenate([centers_initial.reshape(-1), radii_initial])

    def objective(vars):
        centers = vars[:26*2].reshape(26, 2)
        radii = vars[26*2:]
        return -np.sum(radii)

    constraints = []
    for i in range(26):
        constraints.append({'type': 'ineq', 'fun': partial(constraint_x_min, i=i)})
        constraints.append({'type': 'ineq', 'fun': partial(constraint_x_max, i=i)})
        constraints.append({'type': 'ineq', 'fun': partial(constraint_y_min, i=i)})
        constraints.append({'type': 'ineq', 'fun': partial(constraint_y_max, i=i)})
    for i in range(26):
        for j in range(i + 1, 26):
            constraints.append({'type': 'ineq', 'fun': partial(constraint_pairwise, i=i, j=j)})

    result = minimize(
        objective,
        variables_initial,
        method='SLSQP',
        constraints=constraints,
        options={'maxiter': 5000, 'ftol': 1e-10, 'eps': 1e-9}
    )

    optimized_vars = result.x
    centers_opt = optimized_vars[:26*2].reshape(26, 2)
    radii_opt = optimized_vars[26*2:]

    valid = validate_packing(centers_opt, radii_opt)
    if not valid:
        return (centers_initial, radii_initial, 0.0)

    sum_radii = np.sum(radii_opt)
    return (centers_opt, radii_opt, sum_radii)
